import{_ as e,C as t,c as i,o as n,j as a,b as s,a0 as r,a as o,w as l,G as u,a1 as d}from"./chunks/framework.DKRgXLPU.js";const p=JSON.parse('{"title":"Nutrition pour une performance de précision","description":"","frontmatter":{},"headers":[],"relativePath":"fr/education/nutrition/index.md","filePath":"fr/education/nutrition/index.md"}');const c=e({name:"fr/education/nutrition/index.md"},[["render",function(e,p,c,m,g,h){const b=t("Mermaid");return n(),i("div",null,[p[2]||(p[2]=a("h1",{id:"nutrition-pour-une-performance-de-precision",tabindex:"-1"},[o("Nutrition pour une performance de précision "),a("a",{class:"header-anchor",href:"#nutrition-pour-une-performance-de-precision","aria-label":'Permalink to "Nutrition pour une performance de précision"'},"​")],-1)),p[3]||(p[3]=a("p",null,"La pétanque est un sport de précision, pas d'endurance. Vos besoins nutritionnels diffèrent de ceux d'un marathonien ou d'un footballeur. L'essentiel est de maintenir une bonne concentration et une bonne motricité tout au long d'une longue journée de compétition.",-1)),p[4]||(p[4]=a("div",{class:"tip custom-block"},[a("p",{class:"custom-block-title"},"La grande idée"),a("p",null,[a("strong",null,"Votre cerveau est votre outil le plus précieux à la pétanque. Nourrissez-le d'une énergie stable, et non de fluctuations brusques."),o(" Privilégiez les protéines, les bons gras et une bonne hydratation. Évitez les pics de glycémie.")])],-1)),(n(),s(d,null,{default:l(()=>[u(b,{id:"mermaid-11",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BSucres%2FGlucides%20simples%5D%20--%3E%20B%5Bpic%20de%20glyc%C3%A9mie%5D%0A%20%20%20%20B%20--%3E%20C%5BLib%C3%A9ration%20d%26%2339%3Binsuline%5D%0A%20%20%20%20C%20--%3E%20D%5BChute%20de%20glyc%C3%A9mie%5D%0A%20%20%20%20D%20--%3E%20E%5BR%C3%A9ponse%20%C3%A0%20l%26%2339%3Badr%C3%A9naline%5D%0A%20%20%20%20E%20--%3E%20F%5BTremblements%20et%20anxi%C3%A9t%C3%A9%5D%0A%0A%20%20%20%20G%5BProt%C3%A9ines%20et%20graisses%20saines%5D%20--%3E%20H%5BGlyc%C3%A9mie%20stable%5D%0A%20%20%20%20H%20--%3E%20I%5B%C3%89nergie%20constante%5D%0A%20%20%20%20I%20--%3E%20J%5BMise%20au%20point%20nette%5D%0A%20%20%20%20J%20--%3E%20K%5BMains%20fermes%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23ffebee%0A%20%20%20%20style%20F%20fill%3A%23ffebee%0A%20%20%20%20style%20G%20fill%3A%23e8f5e9%0A%20%20%20%20style%20K%20fill%3A%23e8f5e9%0A"})]),fallback:l(()=>[...p[0]||(p[0]=[o(" Loading... ",-1)])]),_:1})),p[5]||(p[5]=r('<h2 id="le-defi-de-l-39-athlete-de-precision" tabindex="-1">Le défi de l&#39;athlète de précision <a class="header-anchor" href="#le-defi-de-l-39-athlete-de-precision" aria-label="Permalink to &quot;Le défi de l&amp;#39;athlète de précision&quot;">​</a></h2><p>Contrairement aux sports de haute intensité, la pétanque ne nécessite pas d&#39;importantes réserves de glycogène ni un apport énergétique rapide. Ce qu&#39;elle requiert, c&#39;est :</p><ul><li><strong>Glycémie stable</strong> - sans pics ni chutes brutales</li><li><strong>Clarté mentale constante</strong> - une concentration qui dure toute la journée</li><li><strong>Mains stables</strong> - sans tremblements ni secousses</li><li><strong>Nervosité apaisée</strong> - faible anxiété et réponse au stress</li></ul><p>Votre stratégie nutritionnelle doit être optimisée en fonction de ces facteurs, et non en fonction de la production brute d&#39;énergie.</p><h2 id="le-probleme-du-sucre-et-des-glucides-simples" tabindex="-1">Le problème du sucre et des glucides simples <a class="header-anchor" href="#le-probleme-du-sucre-et-des-glucides-simples" aria-label="Permalink to &quot;Le problème du sucre et des glucides simples&quot;">​</a></h2><p>De nombreux athlètes optent systématiquement pour des régimes riches en glucides. Chez les joueurs de pétanque, cela peut en réalité nuire à leurs performances.</p><h3 id="les-montagnes-russes-de-la-glycemie" tabindex="-1">Les montagnes russes de la glycémie <a class="header-anchor" href="#les-montagnes-russes-de-la-glycemie" aria-label="Permalink to &quot;Les montagnes russes de la glycémie&quot;">​</a></h3><p>Lorsque vous consommez du sucre ou des glucides simples :</p><ol><li>La glycémie monte en flèche rapidement</li><li>L&#39;insuline est libérée pour faire baisser la tension.</li><li>Chute brutale du taux de sucre dans le sang (hypoglycémie)</li><li>Votre corps libère de l&#39;adrénaline pour compenser.</li><li>Vous souffrez de tremblements, d&#39;anxiété et de difficultés de concentration.</li></ol><p><strong>C&#39;est exactement le contraire de ce dont vous avez besoin pour être précis.</strong></p><h3 id="symptomes-d-39-instabilite-de-la-glycemie" tabindex="-1">Symptômes d&#39;instabilité de la glycémie <a class="header-anchor" href="#symptomes-d-39-instabilite-de-la-glycemie" aria-label="Permalink to &quot;Symptômes d&amp;#39;instabilité de la glycémie&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Symptôme</th><th>Impact sur la performance</th></tr></thead><tbody><tr><td>Mains tremblantes</td><td>Publication incohérente</td></tr><tr><td>Difficultés de concentration</td><td>Mauvaise prise de décision</td></tr><tr><td>Irritabilité</td><td>Conflits d&#39;équipe, manque de sang-froid</td></tr><tr><td>Fatigue après les repas</td><td>Coup de barre de l&#39;après-midi</td></tr><tr><td>Anxiété</td><td>Sensibilité à la pression</td></tr><tr><td>brouillard cérébral</td><td>Réflexion tactique lente</td></tr></tbody></table><h2 id="une-meilleure-approche-l-energie-stable" tabindex="-1">Une meilleure approche : l’énergie stable <a class="header-anchor" href="#une-meilleure-approche-l-energie-stable" aria-label="Permalink to &quot;Une meilleure approche : l’énergie stable&quot;">​</a></h2><p>L&#39;objectif est de fournir à votre cerveau un carburant constant, sans les montagnes russes émotionnelles.</p><h3 id="principes-cles" tabindex="-1">Principes clés <a class="header-anchor" href="#principes-cles" aria-label="Permalink to &quot;Principes clés&quot;">​</a></h3><ol><li><strong>Privilégiez les protéines et les bonnes graisses</strong> - Elles fournissent une énergie lente et constante.</li><li><strong>Privilégiez les glucides complexes aux glucides simples</strong> - Si vous consommez des glucides, choisissez-en qui se digèrent lentement.</li><li><strong>Évitez les pics de glycémie</strong> - Surtout avant et pendant la compétition</li><li><strong>Restez hydraté</strong> - La déshydratation affecte considérablement la concentration</li><li>Mangez régulièrement - Ne vous laissez pas avoir trop faim</li></ol><h3 id="aliments-qui-aident" tabindex="-1">Aliments qui aident <a class="header-anchor" href="#aliments-qui-aident" aria-label="Permalink to &quot;Aliments qui aident&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type d&#39;aliment</th><th>Exemples</th><th>Pourquoi ça marche</th></tr></thead><tbody><tr><td>Protéine</td><td>Œufs, noix, fromage, viande</td><td>Digestion lente, énergie stable</td></tr><tr><td>graisses saines</td><td>Avocat, huile d&#39;olive, noix</td><td>Carburant longue durée</td></tr><tr><td>Glucides complexes</td><td>légumes, légumineuses</td><td>Les fibres ralentissent l&#39;absorption</td></tr><tr><td>Fruits à faible teneur en sucre</td><td>Baies, pommes</td><td>Nutriments sans pic</td></tr></tbody></table><h3 id="aliments-a-limiter" tabindex="-1">Aliments à limiter <a class="header-anchor" href="#aliments-a-limiter" aria-label="Permalink to &quot;Aliments à limiter&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type d&#39;aliment</th><th>Exemples</th><th>Pourquoi c&#39;est problématique</th></tr></thead><tbody><tr><td>Sucre</td><td>Bonbons, sodas, pâtisseries</td><td>pic et chute rapides</td></tr><tr><td>pain blanc/pâtes</td><td>Sandwichs, plats de pâtes</td><td>Conversion rapide en sucre</td></tr><tr><td>Jus de fruit</td><td>Jus d&#39;orange, smoothies</td><td>Sucre concentré</td></tr><tr><td>boissons énergisantes</td><td>La plupart des marques commerciales</td><td>coup de barre après sucre et caféine</td></tr></tbody></table><h2 id="nutrition-le-jour-de-la-competition" tabindex="-1">Nutrition le jour de la compétition <a class="header-anchor" href="#nutrition-le-jour-de-la-competition" aria-label="Permalink to &quot;Nutrition le jour de la compétition&quot;">​</a></h2><h3 id="avant-la-competition" tabindex="-1">Avant la compétition <a class="header-anchor" href="#avant-la-competition" aria-label="Permalink to &quot;Avant la compétition&quot;">​</a></h3><p><strong>2 à 3 heures avant :</strong></p><ul><li>Repas équilibré avec protéines, lipides et légumes</li><li>Évitez les glucides complexes qui pourraient provoquer de la somnolence.</li><li>Exemple : des œufs aux légumes, ou une salade au poulet</li></ul><p><strong>1 heure avant :</strong></p><ul><li>Une collation légère si besoin</li><li>Des noix, du fromage ou une petite portion de protéines</li><li>Évitez tout ce qui est sucré.</li></ul><h3 id="pendant-la-competition" tabindex="-1">Pendant la compétition <a class="header-anchor" href="#pendant-la-competition" aria-label="Permalink to &quot;Pendant la compétition&quot;">​</a></h3><p><strong>Entre les matchs :</strong></p><ul><li>L&#39;eau (le plus important)</li><li>Petites collations protéinées (noix, fromage, viande)</li><li>Évitez les collations et les boissons sucrées</li></ul><p><strong>Signes indiquant que vous avez besoin de manger :</strong></p><ul><li>Difficultés de concentration</li><li>Irritabilité</li><li>Je me sens tremblante</li><li>Mal de tête</li></ul><h3 id="apres-la-competition" tabindex="-1">Après la compétition <a class="header-anchor" href="#apres-la-competition" aria-label="Permalink to &quot;Après la compétition&quot;">​</a></h3><ul><li>Reprenez des forces avec un repas équilibré</li><li>Réhydrater complètement</li><li>Ne vous « récompensez » pas avec du sucre – cela nuira à votre rétablissement</li></ul><h2 id="hydratation" tabindex="-1">Hydratation <a class="header-anchor" href="#hydratation" aria-label="Permalink to &quot;Hydratation&quot;">​</a></h2><p>La déshydratation affecte les fonctions cognitives avant même que l&#39;on ressente la soif.</p><h3 id="lignes-directrices" tabindex="-1">Lignes directrices <a class="header-anchor" href="#lignes-directrices" aria-label="Permalink to &quot;Lignes directrices&quot;">​</a></h3><ul><li><strong>Bien s&#39;hydrater</strong> - Buvez de l&#39;eau tout au long de la journée précédant la compétition.</li><li><strong>Pendant le jeu</strong> - Buvez régulièrement de petites gorgées d&#39;eau, n&#39;attendez pas d&#39;avoir soif.</li><li><strong>Évitez l&#39;excès de caféine</strong> - C&#39;est un diurétique</li><li><strong>Soyez attentif aux signes suivants :</strong> Maux de tête, urine foncée, fatigue</li></ul><h3 id="combien" tabindex="-1">Combien? <a class="header-anchor" href="#combien" aria-label="Permalink to &quot;Combien?&quot;">​</a></h3><p>En règle générale, l&#39;urine doit être jaune pâle. Si elle est foncée, vous devez boire davantage.</p><h2 id="l-39-option-faible-en-glucides" tabindex="-1">L&#39;option faible en glucides <a class="header-anchor" href="#l-39-option-faible-en-glucides" aria-label="Permalink to &quot;L&amp;#39;option faible en glucides&quot;">​</a></h2><p>Certains athlètes de précision adoptent des régimes pauvres en glucides ou cétogènes. La théorie :</p><p><strong>Avantages potentiels :</strong></p><ul><li>Glycémie très stable (aucune hausse possible)</li><li>Clarté mentale constante</li><li>Réduction de l&#39;anxiété et des tremblements</li><li>Pas de baisse d&#39;énergie l&#39;après-midi</li></ul><p><strong>Points à prendre en compte :</strong></p><ul><li>Nécessite une période d&#39;adaptation (1 à 2 semaines)</li><li>Ne convient pas à tout le monde</li><li>Exige de la planification et de l&#39;engagement</li><li>Consultez d&#39;abord un professionnel de la santé.</li></ul><p>Il s&#39;agit d&#39;une stratégie avancée, pas nécessaire pour tout le monde, mais qui mérite d&#39;être envisagée si la stabilité de la glycémie est un problème important pour vous.</p><h2 id="l-39-alimentation-comme-pratique-entrainer-son-corps" tabindex="-1">L&#39;alimentation comme pratique : entraîner son corps <a class="header-anchor" href="#l-39-alimentation-comme-pratique-entrainer-son-corps" aria-label="Permalink to &quot;L&amp;#39;alimentation comme pratique : entraîner son corps&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Concept critique</p><p><strong>La nourriture n&#39;est pas qu&#39;un carburant, c&#39;est un outil d&#39;entraînement.</strong> Tout comme vous vous entraînez à lancer, vous devez vous entraîner à votre nutrition pour que votre corps soit habitué à manger le jour de la compétition.</p></div><h3 id="pourquoi-les-pratiques-alimentaires-sont-importantes" tabindex="-1">Pourquoi les pratiques alimentaires sont importantes <a class="header-anchor" href="#pourquoi-les-pratiques-alimentaires-sont-importantes" aria-label="Permalink to &quot;Pourquoi les pratiques alimentaires sont importantes&quot;">​</a></h3><p>Votre système digestif est capable de s&#39;adapter. Ce que vous mangez régulièrement devient ce à quoi votre corps s&#39;attend et ce qu&#39;il assimile le mieux. Si vous ne consommez que des protéines et des légumes les jours de compétition, votre corps ne s&#39;y adaptera pas.</p><p><strong>Le problème :</strong></p><ul><li>Consommer des aliments inhabituels le jour d&#39;une compétition peut provoquer des troubles digestifs.</li><li>Votre corps a besoin de temps pour s&#39;adapter à de nouvelles habitudes alimentaires.</li><li>Stress + aliments inconnus = risques de troubles digestifs</li><li>L&#39;anxiété de performance est déjà assez pénible sans y ajouter l&#39;anxiété digestive.</li></ul><p><strong>La solution :</strong></p><ul><li>Mettez en pratique votre nutrition de compétition pendant l&#39;entraînement.</li><li>Intégrez vos aliments du jour de compétition à votre routine quotidienne.</li><li>Habituez votre corps à s&#39;acclimater aux aliments à énergie stable</li></ul><h3 id="le-processus-d-39-adaptation" tabindex="-1">Le processus d&#39;adaptation <a class="header-anchor" href="#le-processus-d-39-adaptation" aria-label="Permalink to &quot;Le processus d&amp;#39;adaptation&quot;">​</a></h3>',55)),(n(),s(d,null,{default:l(()=>[u(b,{id:"mermaid-586",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BR%C3%A9gime%20alimentaire%20actuel%5D%20--%3E%20B%5BChangements%20progressifs%5D%0A%20%20%20%20B%20--%3E%20C%5BAdaptation%20corporelle%20%3Cbr%2F%3E%202%20%C3%A0%204%20semaines%5D%0A%20%20%20%20C%20--%3E%20D%5BNouvelle%20normalit%C3%A9%5D%0A%20%20%20%20D%20--%3E%20E%5BPr%C3%AAt%20pour%20la%20comp%C3%A9tition%5D%0A%0A%20%20%20%20F%5BChangement%20soudain%20%3Cbr%2F%3E%20Journ%C3%A9e%20de%20comp%C3%A9tition%5D%20--%3E%20G%5BInconfort%20digestif%5D%0A%20%20%20%20G%20--%3E%20H%5BMauvaises%20performances%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23fff3e0%0A%20%20%20%20style%20E%20fill%3A%23e8f5e9%0A%20%20%20%20style%20F%20fill%3A%23ffebee%0A%20%20%20%20style%20H%20fill%3A%23ffebee%0A"})]),fallback:l(()=>[...p[1]||(p[1]=[o(" Loading... ",-1)])]),_:1})),p[6]||(p[6]=r('<p>Lorsque vous modifiez votre régime alimentaire :</p><ol><li><strong>Semaines 1 et 2 :</strong> Votre corps s’adapte aux nouveaux aliments ; vous pourriez ressentir des changements.</li><li><strong>Semaines 3 et 4 :</strong> L’adaptation se produit, les nouveaux aliments deviennent normaux.</li><li><strong>Semaine 5 et suivantes :</strong> Votre corps est à l&#39;aise et fonctionne efficacement avec ces aliments</li></ol><p><strong>Voilà pourquoi vous ne pouvez pas simplement « manger sainement » le jour de la compétition et espérer des résultats optimaux.</strong></p><h3 id="comment-prendre-soin-de-sa-nutrition" tabindex="-1">Comment prendre soin de sa nutrition <a class="header-anchor" href="#comment-prendre-soin-de-sa-nutrition" aria-label="Permalink to &quot;Comment prendre soin de sa nutrition&quot;">​</a></h3><h4 id="_1-debut-pendant-l-39-entrainement" tabindex="-1">1. Début pendant l&#39;entraînement <a class="header-anchor" href="#_1-debut-pendant-l-39-entrainement" aria-label="Permalink to &quot;1. Début pendant l&amp;#39;entraînement&quot;">​</a></h4><p><strong>Entraînez-vous à manger comme le jour de la compétition pendant vos séances d&#39;entraînement :</strong></p><ul><li>Prenez le même repas avant l&#39;entraînement qu&#39;avant une compétition.</li><li>Apportez les mêmes en-cas que vous emporteriez à un tournoi.</li><li>Observez comment votre corps réagit.</li><li>Ajustez en fonction de ce qui fonctionne</li></ul><p><strong>Exemple de journée de formation :</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>2-3 hours before: Eggs with vegetables (same as competition)</span></span>\n<span class="line"><span>During training: Water + nuts (same as competition)</span></span>\n<span class="line"><span>After training: Balanced meal with protein</span></span></code></pre></div><h4 id="_2-faites-en-votre-habitude" tabindex="-1">2. Faites-en votre habitude <a class="header-anchor" href="#_2-faites-en-votre-habitude" aria-label="Permalink to &quot;2. Faites-en votre habitude&quot;">​</a></h4><p><strong>N&#39;ayez pas un « régime de compétition » et un « régime normal »</strong> - cela crée deux problèmes :</p><ul><li>Votre corps ne s&#39;adapte jamais complètement à l&#39;un ou l&#39;autre.</li><li>Les aliments proposés en compétition sont inhabituels et stressants.</li></ul><p><strong>Plutôt:</strong></p><ul><li>Faites des aliments à énergie stable votre norme quotidienne</li><li>Votre corps devient efficace pour utiliser les protéines et les graisses.</li><li>Le jour de la compétition se déroule normalement, sans différence.</li><li>Aucune surprise digestive</li></ul><h4 id="_3-tester-et-ameliorer" tabindex="-1">3. Tester et améliorer <a class="header-anchor" href="#_3-tester-et-ameliorer" aria-label="Permalink to &quot;3. Tester et améliorer&quot;">​</a></h4><p><strong>Utilisez la formation pour expérimenter :</strong></p><table tabindex="0"><thead><tr><th>Test</th><th>Ce qu&#39;il faut remarquer</th><th>Ajuster</th></tr></thead><tbody><tr><td>Horaires des repas avant l&#39;entraînement</td><td>Niveaux d&#39;énergie, concentration</td><td>Trouvez votre fenêtre optimale</td></tr><tr><td>Différentes sources de protéines</td><td>Digestion, confort</td><td>Identifiez ce qui fonctionne le mieux</td></tr><tr><td>Types de collations</td><td>énergie soutenue</td><td>Trouvez vos en-cas préférés</td></tr><tr><td>quantités d&#39;hydratation</td><td>Concentration, pauses toilettes</td><td>Apport équilibré</td></tr></tbody></table><p><strong>Tenez un journal simple :</strong></p><ul><li>Ce que vous avez mangé et quand</li><li>Comment vous êtes-vous senti pendant l&#39;entraînement</li><li>Niveaux d&#39;énergie et concentration</li><li>Des problèmes digestifs ?</li></ul><h4 id="_4-instaurer-le-confort-et-la-confiance" tabindex="-1">4. Instaurer le confort et la confiance <a class="header-anchor" href="#_4-instaurer-le-confort-et-la-confiance" aria-label="Permalink to &quot;4. Instaurer le confort et la confiance&quot;">​</a></h4><p><strong>Le bénéfice psychologique :</strong></p><p>Lorsque vous avez répété votre plan nutritionnel des centaines de fois à l&#39;entraînement :</p><ul><li>Vous savez exactement comment votre corps va réagir.</li><li>Aucune anxiété concernant les choix alimentaires</li><li>Un souci de moins le jour de la compétition</li><li>Confiance en votre préparation</li></ul><p><strong>C’est le même principe que pour l’entraînement au lancer</strong> : la répétition engendre confort et fiabilité.</p><h3 id="defis-d-39-adaptation-courants" tabindex="-1">Défis d&#39;adaptation courants <a class="header-anchor" href="#defis-d-39-adaptation-courants" aria-label="Permalink to &quot;Défis d&amp;#39;adaptation courants&quot;">​</a></h3><details class="details custom-block"><summary>Transition d&#39;un régime riche en glucides à un régime à énergie stable</summary><p><strong>Défi :</strong> Vous avez l’habitude de manger du pain, des pâtes et des en-cas sucrés.</p><p><strong>Période d&#39;adaptation :</strong> 2 à 4 semaines</p><p><strong>À quoi s&#39;attendre :</strong></p><ul><li>Semaine 1 : Vous pourriez vous sentir différent, avoir envie d&#39;aliments familiers.</li><li>Semaine 2 : L’énergie se stabilise, les envies diminuent</li><li>Semaines 3-4 : Nouvelle normalité, le corps utilise efficacement les graisses et les protéines</li></ul><p><strong>Comment s&#39;entraîner :</strong></p><ul><li>Commencez par un repas à la fois.</li><li>Remplacez d&#39;abord les glucides simples par des glucides complexes.</li><li>Augmentez progressivement les protéines et les graisses saines.</li><li>Commencez par vous entraîner lors de séances à faible enjeu.</li></ul></details><details class="details custom-block"><summary>Trouver les aliments qui vous conviennent</summary><p><strong>Difficulté :</strong> Tout le monde ne digère pas aussi bien les aliments.</p><p><strong>Que faut-il tester :</strong></p><ul><li>Différentes sources de protéines (œufs, viande, noix)</li><li>Moment des repas (2 heures ou 3 heures avant)</li><li>Taille des portions (trop = léthargie, pas assez = faim)</li><li>Certains aliments qui provoquent des inconforts</li></ul><p><strong>Approche pratique :</strong></p><ul><li>Essayez une variable à la fois</li><li>Consacrez 2 à 3 séances d&#39;entraînement à chaque test.</li><li>Notez ce qui vous fait le plus de bien.</li><li>Élaborez votre « menu de compétition » personnel</li></ul></details><details class="details custom-block"><summary>Gestion des environnements alimentaires lors des tournois</summary><p><strong>Difficulté :</strong> Les tournois proposent souvent un choix limité de plats.</p><p><strong>Solution pratique :</strong></p><ul><li>Apportez toujours vos propres collations (prenez-le en pratique).</li><li>Repérer les lieux à l&#39;avance si possible</li><li>Ayez des solutions de secours dont vous savez qu&#39;elles fonctionnent.</li><li>Pratiquez de manger dans différents environnements</li></ul><p><strong>Préparation mentale :</strong></p><ul><li>Ne comptez pas sur la nourriture du lieu de réception.</li><li>Considérez les aliments comme faisant partie de votre équipement.</li><li>Emballez-le comme vous emballez vos boules.</li></ul></details><h3 id="le-plan-de-pratique-nutritionnelle-de-30-jours" tabindex="-1">Le plan de pratique nutritionnelle de 30 jours <a class="header-anchor" href="#le-plan-de-pratique-nutritionnelle-de-30-jours" aria-label="Permalink to &quot;Le plan de pratique nutritionnelle de 30 jours&quot;">​</a></h3><p><strong>Objectif :</strong> Faire d’une alimentation à énergie stable votre normalité.</p><p><strong>Semaines 1 et 2 : Bases</strong></p><ul><li>Remplacez un repas par jour par un repas de type compétition.</li><li>Pratiquez une alimentation adaptée avant l&#39;entraînement</li><li>Commencez à apporter des collations à l&#39;entraînement</li><li>Observez comment votre corps réagit.</li></ul><p><strong>Semaines 3 et 4 : Expansion</strong></p><ul><li>Préparez deux repas par jour axés sur une énergie stable.</li><li>Entraînez-vous à manger comme un jour de compétition les jours d&#39;entraînement.</li><li>Affinez vos choix de collations</li><li>Établissez votre liste d&#39;aliments préférés</li></ul><p><strong>Semaine 5 et suivantes : Maîtrise</strong></p><ul><li>Une alimentation à apport énergétique stable est votre nouvelle norme.</li><li>Le corps est entièrement adapté</li><li>Le jour de la compétition se déroule comme d&#39;habitude</li><li>Confiance en votre nutrition</li></ul><h3 id="votre-kit-alimentaire-de-competition" tabindex="-1">Votre kit alimentaire de compétition <a class="header-anchor" href="#votre-kit-alimentaire-de-competition" aria-label="Permalink to &quot;Votre kit alimentaire de compétition&quot;">​</a></h3><p><strong>Préparez-vous à emporter ceci pour chaque séance d&#39;entraînement :</strong></p><p><strong>Avant la compétition (2 à 3 heures avant) :</strong></p><ul><li>[ ] Source de protéines (œufs, viande ou noix)</li><li>[ ] Légumes ou salade</li><li>[ ] graisses saines (avocat, huile d&#39;olive, fromage)</li></ul><p><strong>Pendant la compétition :</strong></p><ul><li>[ ] Bouteille d&#39;eau (rechargeable)</li><li>[ ] Noix mélangées (petites portions)</li><li>[ ] Œufs durs (si vous pouvez les garder au frais)</li><li>[ ] cubes de fromage ou fromage en bâtonnets</li><li>[ ] viande séchée ou séchée</li><li>[ ] En-cas de secours</li></ul><p><strong>Plus vous vous entraînerez avec ce kit, plus son utilisation deviendra automatique.</strong></p><h2 id="conseils-pratiques" tabindex="-1">Conseils pratiques <a class="header-anchor" href="#conseils-pratiques" aria-label="Permalink to &quot;Conseils pratiques&quot;">​</a></h2><h3 id="collations-faciles-pour-la-competition" tabindex="-1">Collations faciles pour la compétition <a class="header-anchor" href="#collations-faciles-pour-la-competition" aria-label="Permalink to &quot;Collations faciles pour la compétition&quot;">​</a></h3><ul><li>Noix mélangées (non salées)</li><li>Œufs durs</li><li>cubes de fromage</li><li>Bœuf ou dinde séchée</li><li>Légumes avec du houmous</li><li>Olives</li></ul><h3 id="ce-qu-39-il-faut-eviter" tabindex="-1">Ce qu&#39;il faut éviter <a class="header-anchor" href="#ce-qu-39-il-faut-eviter" aria-label="Permalink to &quot;Ce qu&amp;#39;il faut éviter&quot;">​</a></h3><ul><li>distributeurs automatiques de snacks</li><li>Boissons énergétiques sucrées</li><li>Pâtisseries et produits de boulangerie</li><li>Barres de chocolat et de bonbons</li><li>La plupart des barres « énergétiques » (vérifiez la teneur en sucre)</li></ul><h2 id="points-cles-a-retenir" tabindex="-1">Points clés à retenir <a class="header-anchor" href="#points-cles-a-retenir" aria-label="Permalink to &quot;Points clés à retenir&quot;">​</a></h2><blockquote><p>Au pétanque, votre cerveau est votre meilleur atout. Nourrissez-le d&#39;énergie stable, pas d&#39;énergie en dents de scie. Et travaillez votre alimentation comme vous travaillez votre lancer : la répétition engendre confort et régularité.</p></blockquote><p>Privilégiez les protéines, les bons gras et une bonne hydratation. Évitez les pics de glycémie. <strong>Surtout, adoptez les mêmes habitudes alimentaires qu&#39;en compétition.</strong> Votre corps a besoin d&#39;entraînement pour donner le meilleur de lui-même.</p><p><strong>N&#39;oubliez pas :</strong> Vous ne vous présenteriez pas à un tournoi avec une technique de lancer que vous n&#39;avez jamais pratiquée. De même, ne vous présentez pas avec une stratégie nutritionnelle que vous n&#39;avez jamais mise en pratique.</p>',52))])}]]);export{p as __pageData,c as default};
